# One-time trusted local maintenance command. The initial password is generated by the backend and displayed only in an interactive console.
param(
    [Parameter(Mandatory = $true)]
    [ValidatePattern('^[A-Za-z0-9._-]{3,64}$')]
    [string] $LoginName
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$projectRoot = Split-Path $PSScriptRoot -Parent
& (Join-Path $PSScriptRoot 'Use-LocalTools.ps1')

$backend = Join-Path $projectRoot 'backend'
$jar = Join-Path $backend 'target/interview-coach-backend-0.0.1-SNAPSHOT.jar'
if (-not (Test-Path -LiteralPath $jar -PathType Leaf)) {
    throw 'Build the backend JAR first. No account was created.'
}

$originalDirectory = Get-Location
try {
    Set-Location $backend
    & java -jar $jar '--spring.profiles.active=local,provision' '--spring.main.web-application-type=none' "--app.provision.login-name=$LoginName"
    if ($LASTEXITCODE -ne 0) { throw 'Trial account provisioning failed; inspect the non-secret startup error.' }
}
finally {
    Set-Location $originalDirectory
}
